CREATE TABLE "agent_runtime_signals" (
    signal_id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
    agent_id TEXT NOT NULL,
    task_id TEXT REFERENCES tasks(task_id) ON DELETE SET NULL,
    lane_id TEXT REFERENCES lanes(lane_id) ON DELETE SET NULL,
    correlation_id TEXT,
    reason TEXT NOT NULL,
    source_ref TEXT,
    status TEXT NOT NULL,
    created_at TEXT NOT NULL,
    claimed_at TEXT,
    completed_at TEXT,
    error_message TEXT,
    claimed_by TEXT,
    claim_expires_at TEXT,
    attempt_count INTEGER NOT NULL DEFAULT 0,
    last_error TEXT, session_lease_token TEXT, session_fencing_token INTEGER, capability_lease_id TEXT
        REFERENCES agent_capability_lease_records(lease_id) ON DELETE RESTRICT, workspace_generation INTEGER CHECK (
        workspace_generation IS NULL OR workspace_generation > 0
    ),
    record_kind TEXT NOT NULL DEFAULT 'legacy_runtime_signal'
        CHECK (record_kind IN ('legacy_runtime_signal', 'kernel_runtime_signal')),
    agent_member_id TEXT REFERENCES agent_members(member_id) ON DELETE CASCADE,
    claim_token TEXT,
    runtime_lease_generation INTEGER,
    capability_lease_digest TEXT,
    process_epoch INTEGER,
    enqueue_command_digest TEXT,
    claim_command_digest TEXT,
    CHECK (
        record_kind = 'legacy_runtime_signal'
        OR (
            agent_member_id IS NOT NULL
            AND capability_lease_digest IS NOT NULL
            AND process_epoch > 0
            AND enqueue_command_digest IS NOT NULL
        )
    ),
    FOREIGN KEY (session_id, agent_id) REFERENCES agent_members(session_id, agent_id) ON DELETE CASCADE
);

CREATE TABLE approval_requests (
    approval_id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE,
