    intent_digest TEXT,
    scope_id TEXT,
    reason TEXT,
    expires_at TEXT,
    resolver_actor_id TEXT,
    operation_dispatched INTEGER CHECK (operation_dispatched IN (0, 1)),
    CHECK (
        record_kind = 'legacy_approval_request'
        OR (
            requester_actor_id IS NOT NULL
            AND intent_digest IS NOT NULL
            AND scope_id IS NOT NULL
            AND expires_at IS NOT NULL
            AND operation_dispatched IS NOT NULL
        )
    )
);

CREATE TABLE command_receipt_records (
    command_receipt_id TEXT PRIMARY KEY,
    scope_ref TEXT NOT NULL,
    session_id TEXT REFERENCES sessions(session_id) ON DELETE CASCADE,
    command_type TEXT NOT NULL,
    idempotency_key TEXT NOT NULL,
    request_digest TEXT NOT NULL,
    status TEXT NOT NULL,
